-- Archive of the team's Google Sheets — every tab, every number, as-is.
-- Sources:
--   A = Admissions tracker  docs.google.com/spreadsheets/d/1_mmwpl4sqwU2Cte7tk9Lq_qmgRMIjBkJY-s9OyeParc
--   B = Marketing tracker   docs.google.com/spreadsheets/d/1b2uDKfAAG2MdoaexGHIsGZdEquzW2I5p1mP7L56-9hs
-- Additive only. Each row keeps the tab it came from, so when two tabs disagree
-- both are stored and the dashboards choose one per metric. Re-running is safe
-- (on conflict do nothing) and never overwrites anything already there.

create table if not exists archive_monthly (
  sheet text not null,
  tab text not null,
  month_key text not null check (month_key ~ '^\d{4}-\d{2}$'),
  segment text not null default 'all',
  metric text not null,
  value numeric,
  raw text,
  imported_at timestamptz not null default now(),
  primary key (tab, month_key, segment, metric)
);

create table if not exists archive_daily (
  sheet text not null,
  tab text not null,
  day date not null,
  scope text not null,          -- R1 | R2 | R3 | leads | calls:<counselor>
  metric text not null,
  value numeric,
  imported_at timestamptz not null default now(),
  primary key (tab, day, scope, metric)
);

create table if not exists archive_cohort (
  sheet text not null,
  tab text not null,
  cohort text not null,
  metric text not null,
  value numeric,
  pct numeric,
  imported_at timestamptz not null default now(),
  primary key (tab, cohort, metric)
);

create table if not exists archive_campaigns (
  id bigserial primary key,
  sheet text not null,
  tab text not null,
  period text,
  campaign text,
  data jsonb not null,
  imported_at timestamptz not null default now(),
  unique (tab, period, campaign)
);

create table if not exists archive_lead_notes (
  id bigserial primary key,
  sheet text not null,
  tab text not null,
  lead_name text,
  data jsonb not null,
  imported_at timestamptz not null default now(),
  unique (tab, lead_name)
);

create table if not exists archive_notes (
  sheet text not null,
  tab text not null,
  period text not null,
  field text not null,
  note text not null,
  imported_at timestamptz not null default now(),
  primary key (tab, period, field)
);

create index if not exists archive_daily_day_idx on archive_daily (day);
create index if not exists archive_monthly_month_idx on archive_monthly (month_key);

do $$
declare t text;
begin
  foreach t in array array['archive_monthly','archive_daily','archive_cohort','archive_campaigns','archive_lead_notes','archive_notes'] loop
    execute format('alter table %I enable row level security', t);
    execute format('drop policy if exists %I on %I', t || '_read', t);
    execute format('create policy %I on %I for select to authenticated using (true)', t || '_read', t);
  end loop;
end $$;


on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict do nothing;

